//! Primitive-level byte-identity against the reference crate's vectors.txt
//! (generated by gen_vectors.py with independent Python implementations:
//! hashlib/hmac, blake3, cryptography for X25519 and ChaCha20-Poly1305, and
//! kyber-py for ML-KEM-768 — itself validated against the NIST KATs).
//!
//! Only the primitives this crate consumes are re-checked here; the reference
//! also pins SHA-3/SHAKE/Poly1305 internals that live inside the ml-kem and
//! chacha20poly1305 crates now.

use avpn_mix_lane::crypto;
use std::collections::HashMap;
use std::fs;

type VecMap = HashMap<(String, String), Vec<u8>>;

fn vectors() -> VecMap {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/vectors.txt");
    let text = fs::read_to_string(path).expect("vectors.txt next to Cargo.toml");
    let mut map = HashMap::new();
    for line in text.lines() {
        let parts: Vec<&str> = line.split('|').collect();
        assert_eq!(parts.len(), 3, "bad line: {line}");
        let bytes: Vec<u8> = (0..parts[2].len() / 2)
            .map(|i| u8::from_str_radix(&parts[2][2 * i..2 * i + 2], 16).unwrap())
            .collect();
        map.insert((parts[0].to_string(), parts[1].to_string()), bytes);
    }
    map
}

fn get(m: &VecMap, name: &str, field: &str) -> Vec<u8> {
    m.get(&(name.to_string(), field.to_string()))
        .unwrap_or_else(|| panic!("missing {name}|{field}"))
        .clone()
}

fn arr32(b: &[u8]) -> [u8; 32] {
    b.try_into().unwrap()
}
fn arr12(b: &[u8]) -> [u8; 12] {
    b.try_into().unwrap()
}

#[test]
fn cross_sha256_and_hkdf() {
    let v = vectors();
    for i in 0..5 {
        let name = format!("sha256_{i}");
        assert_eq!(
            crypto::sha256(&get(&v, &name, "data")),
            arr32(&get(&v, &name, "digest")),
            "{name}"
        );
    }
    for i in 0..3 {
        let name = format!("hkdf_{i}");
        let ln = get(&v, &name, "len")[0] as usize;
        assert_eq!(
            crypto::hkdf_sha256(
                &get(&v, &name, "salt"),
                &get(&v, &name, "ikm"),
                &get(&v, &name, "info"),
                ln
            ),
            get(&v, &name, "okm"),
            "{name}"
        );
    }
}

#[test]
fn cross_blake3_keyed() {
    let v = vectors();
    for ln in [
        0usize, 1, 64, 65, 1023, 1024, 1025, 2048, 2049, 3072, 4096, 4097, 5000,
    ] {
        let name = format!("blake3k_{ln}");
        let data = get(&v, &name, "data");
        let key = arr32(&get(&v, &name, "key"));
        assert_eq!(
            crypto::blake3_keyed(&key, &data),
            arr32(&get(&v, &name, "hash")),
            "{name}"
        );
    }
}

#[test]
fn cross_x25519() {
    let v = vectors();
    for i in 0..6 {
        let name = format!("x25519_{i}");
        let ask = arr32(&get(&v, &name, "ask"));
        let bpub = arr32(&get(&v, &name, "bpub"));
        assert_eq!(
            crypto::x25519(&ask, &bpub),
            arr32(&get(&v, &name, "ss")),
            "{name} shared secret"
        );
        assert_eq!(
            crypto::x25519_base(&ask),
            arr32(&get(&v, &name, "apub")),
            "{name} base mult"
        );
        let bsk = arr32(&get(&v, &name, "bsk"));
        assert_eq!(
            crypto::x25519(&bsk, &arr32(&get(&v, &name, "apub"))),
            arr32(&get(&v, &name, "ss")),
            "{name} symmetry"
        );
    }
}

#[test]
fn cross_chacha20poly1305() {
    let v = vectors();
    for i in 0..3 {
        let name = format!("aead_{i}");
        let sealed = crypto::aead_seal(
            &arr32(&get(&v, &name, "key")),
            &arr12(&get(&v, &name, "nonce")),
            &get(&v, &name, "aad"),
            &get(&v, &name, "pt"),
        );
        assert_eq!(sealed, get(&v, &name, "sealed"), "{name}");
        let opened = crypto::aead_open(
            &arr32(&get(&v, &name, "key")),
            &arr12(&get(&v, &name, "nonce")),
            &get(&v, &name, "aad"),
            &get(&v, &name, "sealed"),
        )
        .unwrap();
        assert_eq!(opened, get(&v, &name, "pt"), "{name} roundtrip");
        // Tamper: tag fails.
        let mut bad = get(&v, &name, "sealed");
        let last = bad.len() - 1;
        bad[last] ^= 1;
        assert!(crypto::aead_open(
            &arr32(&get(&v, &name, "key")),
            &arr12(&get(&v, &name, "nonce")),
            &get(&v, &name, "aad"),
            &bad
        )
        .is_none());
    }
}

#[test]
fn cross_chacha20_keystream_via_aead_plaintext() {
    // The AEAD vectors pin the keystream indirectly (ct = pt ⊕ ks); pin it
    // DIRECTLY too: seal a run of zeros and compare the leading keystream
    // bytes across two different nonce lengths of input.
    let v = vectors();
    let name = "aead_0";
    let key = arr32(&get(&v, name, "key"));
    let nonce = arr12(&get(&v, name, "nonce"));
    let pt = get(&v, name, "pt");
    let sealed = crypto::aead_seal(&key, &nonce, &[], &pt);
    let ks = crypto::chacha20_keystream(&key, &nonce, pt.len());
    for i in 0..pt.len() {
        assert_eq!(sealed[i], pt[i] ^ ks[i], "keystream mismatch at {i}");
    }
}

#[test]
fn cross_mlkem768() {
    let v = vectors();
    for i in 0..4 {
        let name = format!("mlkem_{i}");
        let d = arr32(&get(&v, &name, "d"));
        let z = arr32(&get(&v, &name, "z"));
        let (ek, dk) = crypto::mlkem_keygen(&d, &z);
        assert_eq!(ek, get(&v, &name, "ek"), "{name} ek (wire format!)");
        assert_eq!(dk, get(&v, &name, "dk"), "{name} dk (wire format!)");
        let m = arr32(&get(&v, &name, "m"));
        let (k, c) = crypto::mlkem_encaps(&ek, &m).unwrap();
        assert_eq!(k, get(&v, &name, "K"), "{name} shared secret");
        assert_eq!(c, get(&v, &name, "c"), "{name} ciphertext (wire format!)");
        let k2 = crypto::mlkem_decaps(&dk, &c).unwrap();
        assert_eq!(k2, get(&v, &name, "K"), "{name} decaps");
        // Implicit rejection: tampered ct yields the same deterministic
        // garbage key as the reference (FIPS 203 J(z||c')).
        let mut bad = c.clone();
        bad[17] ^= 0x40;
        assert_eq!(
            crypto::mlkem_decaps(&dk, &bad).unwrap(),
            get(&v, &name, "Kbad"),
            "{name} implicit rejection"
        );
    }
}
